/* @author MILO-GAO(高振銘)@2020 */ package page2020.flow;import java.util.ArrayList;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Component;import page2020.View;import page2020.core.App;import page2020.core.Log;import page2020.core.Name.PageKey;import page2020.core.Name.Path;import page2020.core.Page;import page2020.unit.Func;import page2020.unit.Menu;import page2020.unit.Udialog;import page2020.view.B4;import page2020.view.C3;import page2020.view.Content;import page2020.view.Element;import page2020.view.H5;import page2020.view.Text;import page2020.view.Value;import page2020.view.bs4.B4button.BtnColor;import page2020.view.bs4.B4color.Color;import page2020.view.bs4.B4ctrl;import page2020.view.bs4.B4dropdown;import page2020.view.bs4.B4element;import page2020.view.bs4.B4listGroup;import page2020.view.bs4.B4nav;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4show.P;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3color.White;import page2020.view.css3.C3show.Overflow;import page2020.view.css3.C3show.Position;import page2020.view.css3.C3show.Visible;import page2020.view.html5.H5a;import page2020.view.html5.H5button;import page2020.view.html5.H5header;import page2020.view.html5.H5main;import secure2020.data.SecureUser;@Componentpublic class HealthPersonal implements Personal {	private static Logger log = LoggerFactory.getLogger(HealthPersonal.class);	private static final String permit = "permit";	private Menu menuTree = App.menuTree("health");	@Autowired	private SecureUser user;	@Override	public View home(String sysCode) {		if (Log.layout) {			log.info("home: sysCode='" + sysCode + "'");		}		return new View();	}	@Override	public List<String> script() {		List<String> array = new ArrayList<String>();		array.add(Path.page2020 + "layout.health.js");		array.add(Path.page2020 + "layout.password.js");		if (Log.layout) {			log.info("script: '" + Path.page2020 + "layout.health.js'");			log.info("script: '" + Path.page2020 + "layout.password.js'");		}		return array;	}	@Override	public Element<?, ?> navbar(Page page) {		B4element navbar = (B4element) this.user.getNavbars().get("health");		if (Log.layout) {			log.info("navbar: page='" + page.getApp().getName() + "', user='" + this.user.getFullname() + "'");		}		if (navbar == null) {			navbar= B4.element().name(PageKey.navbar).center().px(3)				.css(C3.color(White.White))				.css(C3.bg.image(Path.icons + "h365-header.svg"))				.cssClass(P.fixTop).height("3rem");			Text userInfo = H5.text().text(this.user.getFullname() + "&nbsp;" + this.user.getTitle());			B4dropdown userDropdown = B4.dropdown()				.button(true, B4.button(BtnColor.link).append(userInfo))				.menu()					.item(B4.button(BtnColor.link).data(PageKey.tool, "logout").icon("sign-out-alt").code("app.health.logout"))					.item(B4.button(BtnColor.link).data(PageKey.tool, "password").icon("passport").code("app.health.password"))					.divider()					.item(B4.button(BtnColor.link).data(PageKey.lang, "zh_TW").icon("language").code("page2020.lang.zh_TW"))					.item(B4.button(BtnColor.link).data(PageKey.lang, "en").icon("language").code("page2020.lang.en"))				.boxes();			((H5button) userDropdown.get(0)).css(C3.color(White.White)).disabled(true);			((H5button) userDropdown.get(1)).css(C3.color(White.White));			page.selector("div[data-name='" + PageKey.navbar + "'] button[disabled]", 				C3.color(White.White), C3.color.opacity(1.0));			navbar.append(				H5.span().cssClass("mr-5").code(App.sysCodeKey("health")),				H5.span().data(PageKey.tool, "hide").append(H5.icon("outdent").size("2x")),				H5.span().data(PageKey.tool, "show").append(H5.icon("indent").size("2x")).cssClass(D.none),				userDropdown.cssClass(P.mlAuto)			);			this.user.getNavbars().put("health", navbar);			if (Log.layout) {				log.info("navbar: (new) " + this.user.getFullname());			}		}		this.user.setNavbar(navbar);		return navbar;	}	@Override	public Element<?, ?> menu(Page page) {		this.cssMenuItemE("div[data-name='" + PageKey.menu + "'] a", page);		B4element menu = (B4element) this.user.getMenus().get("health");		if (Log.layout) {			log.info("menu: page='" + page.getApp().getName() + "', user='" + this.user.getFullname() + "'");		}		if (menu == null) {			menu = B4.element().name(PageKey.menu).css(				C3.bg(White.White), C3.show.overflowY(Overflow.auto),				C3.show.position(Position.fixed),				C3.box.left("0"), C3.box.top("3rem"), C3.width("10rem"), C3.height("auto")			);			B4listGroup listGroup = B4.listGroup(true).width("100%");			menu.append(listGroup);			if (this.menuTree != null) {				int size = this.menuTree.getChildren().size();				for (int i=0; i < size; i++) {					Menu topMenu = this.menuTree.getChildren().get(i);					if (topMenu.getFuncList().isEmpty()) {						continue;					}					Func function = topMenu.getFuncList().get(0);					int pos = function.getCode().indexOf(".");					String code = function.getCode().substring(pos + 1);					if (! this.user.getPermission().contains(code)) {						continue;					}					if (Log.layout) {						log.info("menu: permission='" + code + "'");					}					listGroup.item(H5.a().href(function.getAction())						.cssClass("px-0", "pt-2", "pb-1", TextX.center)						.data("code", function.getName())							.append(							H5.div().icon(function.getIcon()),							H5.div().cssClass("func-code").code(function.getCode())						)					);					if (Log.layout) {						log.info("menu: menu[" + i + "]='" + function.getAction() + "'");					}				}			}			this.user.getMenus().put("health", menu);		}		this.user.setMenu(menu);		B4listGroup group = (B4listGroup) menu.get(0);		int size = group.count();		for (int i=0; i < size; i++) {			H5a a = (H5a) group.get(i);			String code = (String) a.getData("code");			if (page.getApp().getAppCode().startsWith(code)) {				a.cssClass(B4ctrl.active);				if (Log.layout) {					log.info("menu: active='" + code + "'");				}			} else {				a.removeClass(B4ctrl.active);			}		}		return menu;	}	@Override	public H5header header(Page page, Func func) {		H5header header = H5.header().name(PageKey.header).cssClass("mt-4", "mr-4", "ml-4");		String navItemE = "header[data-name='" + PageKey.header + "'] ul[data-type='nav'] li.nav-item";		this.cssNavItemE(navItemE, page);		List<Func> functions = null;		String menuCode = null;		if (func != null && func.getName().contains(".")) {			if (Log.layout) {				log.info("header: page='" + page.getApp().getName() + "', function='" + func.getName() + "'");			}			String[] tokens = func.getName().split("\\.");			if (tokens.length >= 2) {				Menu menu = App.menu(tokens[0] + "." + tokens[1]);				if (menu != null && (! menu.getFuncList().isEmpty())) {					functions = menu.getFuncList();					if (tokens.length >= 3) {						menuCode = tokens[0] + "." + tokens[1] + "." + tokens[2];					}					if (Log.layout) {						log.info("header: menu='" + menu.getName() + "', links=" + functions.size()							+ ", menuCode='" + menuCode + "'");					}				}			}		}		B4nav nav = B4.nav();		header.append(nav);		if (functions != null) {			int size = functions.size();			for (int i=1; i < size; i++) {				Func function = functions.get(i);				H5a a = H5.a().href(function.getAction()).code(function.getCode());				nav.item(a);				B4element li = (B4element) nav.boxes().last();  				li.data(permit, function.getName());					if (Log.layout) {					log.info("header: link[" + i + "]='" + function.getAction() + "'");				}				if (menuCode != null && function.getName().startsWith(menuCode)) {					li.cssClass(B4ctrl.active);					a.cssClass(B4ctrl.active);					if (Log.layout) {						log.info("header: active='" + function.getAction() + "'");					}				}			}		}		return header;	}	@Override	public B4element buttonBox(Page page, B4element buttonBox) {		if (Log.layout) {			log.info("buttonBox: count=" + buttonBox.count());		}				return buttonBox.cssClass(D.none);	}	@Override	public H5main main(Page page, H5main main) {		if (Log.layout) {			log.info("main: count=" + main.count());		}				return main.cssClass("mx-4", "p-3").css(C3.bg(White.White), C3.show.overflowY(Overflow.auto));	}	public void layout(Page page) {		B4element content = (B4element) page.get(0);		content.css(C3.show.position(Position.fixed),			C3.box.left("10rem"), C3.box.top("3rem"), C3.width("auto"), C3.height("auto")		);		if (Log.layout) {			log.info("layout: page='" + page.getApp().getName() + "', user='" + this.user.getFullname() + "'");		}		H5header header = (H5header) page.find(PageKey.header);		B4nav nav = null;		if (header != null) {			nav = (B4nav) header.find(null, "ul", B4nav.nav);		}		if (nav != null) {			int index = 0;			nav.boxes();			while (index < nav.count()) {				B4element li = (B4element) nav.get(index);				String code = (String) li.getData(permit);				li.removeData(permit);					if (! this.user.getPermission().contains(code)) {					nav.remove(index);				} else {					if (Log.layout) {						log.info("layout: permission='" + code + "'");					}					index ++;				}			}		}		Udialog dialog = null;		H5main main = (H5main) content.find(null, "main", null);		int count = main.count();		for (int i=0; i < count; i++) {			Content<?> c = main.get(i);			if (c instanceof Udialog) {				dialog = (Udialog) c;				page.append(main.remove(i));				if (Log.layout) {					log.info("layout: dialog");				}				break;			}		}		String appCode = null;		List<Func> functions = new ArrayList<Func>();		if (dialog != null) {			appCode = page.getApp().getAppCode();			if (appCode.endsWith(".insert") || appCode.endsWith(".update")) {				appCode = appCode.substring(0, appCode.length() - 7);			}			if (Log.layout) {				log.info(page.getApp().toString());				log.info("layout: appCode='" + appCode + "'");			}			String tabCode = null;			if (appCode.contains(".")) {				String[] tokens = appCode.split("\\.");				if (tokens.length >= 3) {					tabCode = String.format("%s.%s.%s", tokens[0], tokens[1], tokens[2]);					Menu menu = App.menu(tabCode);					if (menu != null) {						int size = menu.getFuncList().size();						for (int i=0; i < size; i++) {							Func function = menu.getFuncList().get(i);							if (this.user.getPermission().contains(appCode)) {								functions.add(function);								if (Log.layout) {									log.info("layout: permission='" + function.getName() + "'");								}							}						}						if (Log.layout) {							log.info("layout: menu='" + menu.getName() + "', tab='" + tabCode 								+ "', actions=" + functions.size());						}					}				}			}		}		if (! functions.isEmpty()) {			this.cssNavItemE("div[data-name='" + PageKey.dialog + "'] ul[data-type='nav'] li.nav-item", page);			B4element board = dialog.board().css(C3.bg("#f3f3f3"));			B4nav tabNav = B4.nav();			B4element container = B4.element().p(3).css(C3.bg("#fff"));			while (board.count() > 0) {				container.append(board.remove(0));			}			board.append(tabNav, container);			boolean standalone = false;			int size = functions.size();			for (int i=0; i < size; i++) {				Func function = functions.get(i);				H5a a = H5.a().href(function.getAction()).code(function.getCode());				tabNav.item(a);				if (Log.layout) {					log.info("layout: tab[" + i + "]='" + function.getAction() + "'");				}				if (appCode.startsWith(function.getName())) {					((B4element) tabNav.boxes().last()).cssClass(B4ctrl.active);					a.cssClass(B4ctrl.active);					dialog.css(C3.show.visibility(Visible.visible));										if (function.getName().endsWith("_i")) {						a.add(0, App.icon("link_i"));						a.cssClass(Color.success);						standalone = true;					} else if (function.getName().endsWith("_u")) {						a.add(0, App.icon("link_u"));						a.cssClass(Color.warning);						standalone = true;					} else if (function.getName().endsWith("_d")) {						a.add(0, App.icon("link_d"));						a.cssClass(Color.danger);						standalone = true;					} else if (function.getName().endsWith("_v")) {						tabNav.cssClass(D.none);					}					if (Log.layout) {						log.info("layout: tab[" + i + "]=active");					}				}			}			if (standalone) {				tabNav.standalone();			}		}		page.append(this.navbar(page), this.menu(page));	}	private void cssMenuItemE(String aE, Page page) {		Value[] activeStyles = new Value[] {			C3.color("#1890ff"), C3.color.opacity(1.0), C3.bg("#e6f7ff"),			C3.border.color("rgba(0,0,0,0.125)"), C3.border.border("right", "solid 4px #1890ff")		};		page.selector(aE, C3.color("rgba(0,0,0,0.65)"), C3.border.border("right", "solid 4px #fff"));		page.selector(aE + ":hover", activeStyles);		page.selector(aE + ":active", activeStyles);		page.selector(aE + ".active", activeStyles);	}	private void cssNavItemE(String navItemE, Page page) {		Value[] activeItemStyles = new Value[] { 			C3.border.border("top", "solid 2px #00809f")		};		Value[] activeLinkStyles = new Value[] {			C3.color("#00809f"), C3.color.opacity(1.0), C3.bg("#fff")			};		page.selector(navItemE, C3.border.border("top", "solid 2px #f3f3f3"));		page.selector(navItemE + " a", C3.color("rgba(0,0,0,0.65)"));		page.selector(navItemE + ":hover", activeItemStyles);		page.selector(navItemE + ".active", activeItemStyles);		page.selector(navItemE + " a:hover", activeLinkStyles);		page.selector(navItemE + " a.active", activeLinkStyles);	}}